revision.text:
{{
Mathematischer Text/Lösung{{{opt|}}}
|Text=
Der Richtungsvektor der Geraden ist {{mathl|term= {{op:Spaltenvektor| 5| -3}} |SZ=.}} Somit besitzt die Geradengleichung die Form
{{
Relationskette/display
| 3x+5y
|| c
||
||
||
|SZ=.
}}
Einsetzen eines Punkt ergibt
{{
Relationskette
|c
|| 2
||
||
||
|SZ=.
}}
Somit ist
{{
Relationskette/display
| y 
|| {{op:Bruch| 2- 3x| 5}}
||
||
||
|SZ=.
}}
Dies setzen wir in die Kreisgleichung
{{
Relationskette/display
| x^2+y^2
|| 1
||
||
||
|SZ=
}}
ein und erhalten
{{
Relationskette/display
| x^2 + {{makl| {{op:Bruch| 2- 3x| 5}}  |}}^2 
|| 1
||
||
||
|SZ=
}}
oder
{{
Relationskette/display
| x^2  +   {{op:Bruch| 4 - 12x +9x^2 | 25}}     -1 
|| {{op:Bruch| 34 | 25}}  x^2 - {{op:Bruch| 12 | 25}} x - {{op:Bruch| 21 | 25}}
|| 0
||
||
|SZ=.
}}
Die Normierung davon ist
{{
Math/display|term=
 x^2 - {{op:Bruch| 6 | 17}} x - {{op:Bruch| 21 | 34}}
|SZ=.
}}
Somit ist
{{
Relationskette/align
| x_{1,2}
|| {{op:Bruch| {{op:Bruch| 6 | 17}} \pm \sqrt{ {{makl| {{op:Bruch| 6 | 17}} |}}^2 + 4 \cdot {{op:Bruch| 21 | 34}}   }| 2}} 
|| {{op:Bruch| {{op:Bruch| 6 | 17}} \pm \sqrt{ {{makl| {{op:Bruch| 6 | 17}} |}}^2 + {{op:Bruch| 42 | 17 }}   }| 2}} 
|| {{op:Bruch|   6   \pm \sqrt{  6^2 + 714   }| 34 }} 
|| {{op:Bruch|   6   \pm \sqrt{  750   }| 34 }} 
|| {{op:Bruch|   6   \pm 5 \sqrt{  30   }| 34 }} 
|SZ=
}}
und
{{
Relationskette/align
| y_{1,2} 
|| {{op:Bruch| 2- 3x_{1,2} | 5}}
|| {{op:Bruch|     2- 3 {{makl| {{op:Bruch|  6   \pm 5 \sqrt{  30   }  | 34 }}    }}             | 5}}
|| {{op:Bruch| 68 - 3 {{makl|    6   \pm 5 \sqrt{  30   }     }}       | 170}}
|| {{op:Bruch| 50       \mp 15 \sqrt{  30   }           | 170}}
|| {{op:Bruch| 10      \mp 3 \sqrt{  30   }           | 34}}
|SZ=.
}}
Die Schnittpunkte sind also
{{
Mathkor/display|term1=
 {{op:Zeilenvektor| {{op:Bruch|   6  + 5 \sqrt{  30   }| 34 }}  |{{op:Bruch| 10 - 3 \sqrt{  30   }           | 34}} }}
|und|term2=
 {{op:Zeilenvektor| {{op:Bruch|   6  - 5 \sqrt{  30   }| 34 }}  |{{op:Bruch| 10  + 3 \sqrt{  30   }           | 34 }} }}
|SZ=.
}}
